import { test, expect, Page, Locator } from '@playwright/test';
import * as path from 'path';
import { addDays, dotDate, isoDate } from '../_helpers/dates';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/user1.json'),
  viewport: { width: 390, height: 844 },
});

// «Сегодня»/«завтра» — реальные (часы браузера НЕ сдвигаются: сдвиг назад ломал сессию — 401, см. .qa/context.md).
// В кейсе это 2026-10-03 / 2026-10-04 («04.10.2026»); здесь те же роли дат вычисляются от реального дня.
const NOW = new Date();
const TODAY = isoDate(NOW);
const TOMORROW = isoDate(addDays(NOW, 1));
const TOMORROW_DOT = dotDate(addDays(NOW, 1));

// Выбрать день в календаре окна; если «завтра» уже в следующем месяце — перейти «החודש הבא».
async function pickDay(dialog: Locator, iso: string) {
  await expect(dialog.getByRole('radio').first()).toBeVisible();
  const radio = dialog.getByRole('radio', { name: new RegExp(`^${iso}, `) });
  if ((await radio.count()) === 0) await dialog.getByRole('button', { name: 'החודש הבא' }).click();
  await radio.click();
}

async function deleteQaDates(page: Page) {
  await page.goto('/home');
  await expect(page.getByRole('button', { name: 'הוספת תאריך חשוב' })).toBeVisible({ timeout: 20_000 });
  await page.waitForLoadState('networkidle').catch(() => {});
  const edit = page.getByRole('button', { name: /QA-AUTO-.*: פתיחה לעריכה$/ });
  for (let guard = 0; guard < 10; guard++) {
    const before = await edit.count();
    if (before === 0) break;
    await edit.first().click();
    await page.getByRole('button', { name: 'מחיקת התאריך' }).click();
    await page.getByRole('button', { name: 'מחיקה', exact: true }).click();
    await expect(edit).toHaveCount(before - 1);
  }
}

test.describe('Важные даты и אזכרות', () => {
  test('ID-02 Карандаш → правка (имя, дата, тип) → сохранить → удалить с подтверждением #6a86f7e6 @data @mobile', async ({ page }) => {
    try {
      // 1. `/home` → «הוספת תאריך חשוב» → «תאריך חשוב» → «שם התאריך» = «QA-AUTO-היום», день = сегодня → «הוסף תאריך».
      await page.goto('/home');
      await page.getByRole('button', { name: 'הוספת תאריך חשוב' }).click();
      await page.getByRole('button', { name: 'תאריך חשוב', exact: true }).click();
      let dialog = page.getByRole('dialog');
      await dialog.getByRole('textbox', { name: 'שם התאריך' }).fill('QA-AUTO-היום');
      await pickDay(dialog, TODAY);
      await dialog.getByRole('button', { name: 'הוסף תאריך' }).click();
      await expect(page.getByRole('dialog')).toHaveCount(0);

      // 2. Карандаш → окно «עריכת תאריך»: поля; имя → «QA-AUTO-מחר», день → завтра → «שמירת השינויים»; reload.
      await page.getByRole('button', { name: 'QA-AUTO-היום: פתיחה לעריכה' }).click();
      dialog = page.getByRole('dialog');
      await expect(dialog.getByText('עריכת תאריך', { exact: true })).toBeVisible();
      await expect(dialog.getByRole('radio', { name: 'תאריך חשוב', exact: true })).toHaveAttribute('aria-checked', 'true');
      await expect(dialog.getByRole('radio', { name: 'אזכרה', exact: true })).toHaveAttribute('aria-checked', 'false');
      const nameField = dialog.getByRole('textbox', { name: 'שם התאריך' });
      await expect(nameField).toHaveValue('QA-AUTO-היום');
      await expect(dialog.getByRole('radio', { name: new RegExp(`^${TODAY}, `) })).toHaveAttribute('aria-checked', 'true');
      await expect(dialog.getByRole('button', { name: 'שמירת השינויים' })).toBeVisible();
      await expect(dialog.getByRole('button', { name: 'מחיקת התאריך' })).toBeVisible();

      await nameField.fill('QA-AUTO-מחר');
      await pickDay(dialog, TOMORROW);
      await dialog.getByRole('button', { name: 'שמירת השינויים' }).click();
      await expect(page.getByRole('dialog')).toHaveCount(0);
      await page.reload();
      await expect(page.getByRole('button', { name: 'QA-AUTO-מחר: פתיחה לעריכה' })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('QA-AUTO-היום')).toHaveCount(0);
      await expect(page.getByText(TOMORROW_DOT).first()).toBeVisible();

      // 3. Карандаш → тип «אזכרה» (не сохранять) → поля; день в будущем → закрыть без сохранения.
      await page.getByRole('button', { name: 'QA-AUTO-מחר: פתיחה לעריכה' }).click();
      dialog = page.getByRole('dialog');
      await dialog.getByRole('radio', { name: 'אזכרה', exact: true }).click();
      await expect(dialog.getByRole('textbox', { name: 'שם הנפטר' })).toBeVisible();
      await expect(dialog.getByRole('checkbox', { name: 'הפטירה הייתה אחרי השקיעה' })).toBeVisible();
      // выбран завтрашний (будущий) день
      await expect(dialog.getByRole('radio', { name: new RegExp(`^${TOMORROW}, .*לא ניתן לבחור תאריך עתידי`) })).toHaveAttribute('aria-disabled', 'true');
      await expect(dialog.getByText('תאריך הפטירה לא יכול להיות בעתיד.')).toBeVisible();
      await expect(dialog.getByRole('button', { name: 'שמירת השינויים' })).toBeDisabled();
      await dialog.getByRole('button', { name: 'סגירה' }).click();
      await expect(page.getByRole('dialog')).toHaveCount(0);
      await expect(page.getByRole('button', { name: 'QA-AUTO-מחר: פתיחה לעריכה' })).toBeVisible();
    } finally {
      // 4. Уборка: карандаш → «מחיקת התאריך» → окно → «מחיקה»; reload `/home` и `/profile`.
      // (прочитать окно подтверждения — до удаления)
      await page.goto('/home');
      const pencil = page.getByRole('button', { name: /QA-AUTO-.*: פתיחה לעריכה$/ });
      await expect(page.getByRole('button', { name: 'הוספת תאריך חשוב' })).toBeVisible({ timeout: 20_000 });
      await page.waitForLoadState('networkidle').catch(() => {});
      if ((await pencil.count()) > 0 && (await pencil.first().getAttribute('aria-label')) === 'QA-AUTO-מחר: פתיחה לעריכה') {
        await pencil.first().click();
        await page.getByRole('button', { name: 'מחיקת התאריך' }).click();
        const confirm = page.getByRole('dialog');
        await expect(confirm.getByText('למחוק את התאריך?')).toBeVisible();
        await expect(confirm.getByText('«QA-AUTO-מחר» יימחק מהתאריכים החשובים שלך, ואי אפשר יהיה לשחזר אותו.')).toBeVisible();
        await expect(confirm.getByRole('button', { name: 'ביטול' })).toBeVisible();
        await confirm.getByRole('button', { name: 'מחיקה', exact: true }).click();
        await expect(page.getByRole('dialog')).toHaveCount(0);
      }
      await deleteQaDates(page); // подстраховка: любые другие «QA-AUTO-…»
      await page.reload();
      await expect(page.getByRole('button', { name: 'הוספת תאריך חשוב' })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('QA-AUTO-')).toHaveCount(0);
      await page.goto('/profile');
      await expect(page.getByRole('heading', { name: 'תאריכים חשובים' })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('QA-AUTO-')).toHaveCount(0);
    }
  });
});
